import{_ as o,C as i,o as n,c as r,j as e,a as d,E as s,a2 as l}from"./chunks/framework.DrWxItG4.js";const f=JSON.parse('{"title":"9 NETSTATE_SNAPSHOT","description":"","frontmatter":{},"headers":[],"relativePath":"messages/9-netstate-snapshot.md","filePath":"messages/9-netstate-snapshot.md"}'),h={name:"messages/9-netstate-snapshot.md"};function c(p,t,u,b,y,m){const a=i("Badge");return n(),r("div",null,[t[0]||(t[0]=e("h1",{id:"_9-netstate-snapshot",tabindex:"-1"},[d("9 NETSTATE_SNAPSHOT "),e("a",{class:"header-anchor",href:"#_9-netstate-snapshot","aria-label":'Permalink to "9 NETSTATE_SNAPSHOT"'},"​")],-1)),s(a,{type:"info",text:"message type"}),t[1]||(t[1]=d()),s(a,{type:"info",text:"server → client"}),t[2]||(t[2]=e("p",null,`A binary state snapshot for the client's "NetState" system, used only in some worlds (probably PvE / dungeon). The name is this site's; the client has none.`,-1)),t[3]||(t[3]=e("h2",{id:"what-the-client-does-with-it",tabindex:"-1"},[d("What the client does with it "),e("a",{class:"header-anchor",href:"#what-the-client-does-with-it","aria-label":'Permalink to "What the client does with it"'},"​")],-1)),s(a,{type:"tip",text:"decompiled from the 5.60 client"}),t[4]||(t[4]=l('<p><strong>Server → client</strong>, a binary state snapshot for the client&#39;s &quot;NetState&quot; system (its logs use that name). It goes with the <a href="/gtps-guide/messages/10-netstate-frame">type 10 and 11</a> messages the client sends in worlds that use this system (worlds with flag 0x200 in world+0x1a0, or bit 0 of the version-27 trailer int, see <a href="/gtps-guide/guide/world-data">World data</a>); probably the PvE / dungeon worlds. Neither gurotopia nor GrowServer uses it.</p><p>Layout after the <code>u32 9</code>:</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>u32</td><td>tick</td><td>the snapshot&#39;s time</td></tr><tr><td>u8 n</td><td>count</td><td>at most 100</td></tr><tr><td>n × 8 bytes</td><td>entries A</td><td>keyed by their first byte (an id); merged into the snapshot with the same tick. Meaning not traced</td></tr><tr><td>u8 m</td><td>count</td><td>at most 100</td></tr><tr><td>m × 24 bytes</td><td>player states</td><td>keyed by their first byte (a netID), see below</td></tr></tbody></table><p>Player state (24 bytes), as the client applies it to <strong>your own</strong> avatar (<code>0x1b3bfac</code>):</p><table tabindex="0"><thead><tr><th>Offset</th><th>Size</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td>u8</td><td>netID</td></tr><tr><td>3</td><td>u8</td><td>a value used as a 0–1 fraction (/255)</td></tr><tr><td>4</td><td>u32</td><td>the last input number the server processed. The client drops inputs up to it and replays the later ones, so this is probably server reconciliation of client-side prediction</td></tr><tr><td>8</td><td>u32</td><td>not traced</td></tr><tr><td>14, 16</td><td>u16, u16</td><td>position (unsigned)</td></tr><tr><td>18, 20</td><td>i16, i16</td><td>velocity</td></tr><tr><td>22</td><td>u8</td><td>a second 0–1 fraction (/255)</td></tr><tr><td>23</td><td>u8</td><td>not traced</td></tr></tbody></table><p>What the client does:</p><ul><li>An older tick than the newest buffered one is skipped (&quot;Skip snapshot. Snapshot time: {}, comparisonTime {}&quot;).</li><li>The same tick is merged into that snapshot (entries with the same key are replaced).</li><li>A newer tick is added to a ring buffer, and the client sets its clock to <code>tick − 250</code>.</li><li>More than 100 entries throws &quot;Snapshot target array capacity exceeded&quot;.</li><li>Only the entry with your own netID is applied, and only while you&#39;re in a world.</li></ul><p><small>Case 9 of the dispatcher <code>0x114276c</code> → <code>0x1b3c7bc</code>; parser <code>0x1348d64</code>; merge <code>0x1b3caa8</code>, <code>0x1b3ccf0</code>; apply <code>0x1b3bed4</code> → <code>0x1b3bfac</code>.</small></p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[u32 9][...]</span></span></code></pre></div>',10))])}const w=o(h,[["render",c]]);export{f as __pageData,w as default};
